import{_ as i,C as c,o,c as n,a2 as a,b as s,w as t,a as l,E as d,a3 as p}from"./chunks/framework.CAUU6m5Y.js";const f=JSON.parse('{"title":"F3: Automated Hold Expiration & Stock Rollback","description":"","frontmatter":{},"headers":[],"relativePath":"features/F3-hold-expiration-rollback.md","filePath":"features/F3-hold-expiration-rollback.md"}'),u={name:"features/F3-hold-expiration-rollback.md"};function h(m,e,k,v,b,_){const r=c("Mermaid");return o(),n("div",null,[e[1]||(e[1]=a('<h1 id="f3-automated-hold-expiration-stock-rollback" tabindex="-1">F3: Automated Hold Expiration &amp; Stock Rollback <a class="header-anchor" href="#f3-automated-hold-expiration-stock-rollback" aria-label="Permalink to &quot;F3: Automated Hold Expiration &amp; Stock Rollback&quot;">​</a></h1><h2 id="technical-overview" tabindex="-1">Technical Overview <a class="header-anchor" href="#technical-overview" aria-label="Permalink to &quot;Technical Overview&quot;">​</a></h2><p>When a customer reserves stock, inventory is shifted from <code>available</code> to <code>reserved</code> with a 300-second TTL (<code>models/inventory.py:47</code>). If payment confirmation is not completed before the TTL expires, the hold is marked <code>EXPIRED</code>, and the reserved units are atomically rolled back to <code>available</code> stock.</p>',3)),(o(),s(p,null,{default:t(()=>[d(r,{id:"mermaid-9",class:"mermaid",graph:"stateDiagram-v2%0A%20%20%20%20%5B*%5D%20--%3E%20PENDING%3A%20User%20reserves%20stock%20(300s%20TTL)%0A%20%20%20%20PENDING%20--%3E%20CONFIRMED%3A%20Payment%20succeeds%0A%20%20%20%20CONFIRMED%20--%3E%20%5B*%5D%3A%20Order%20fulfilled%0A%20%20%20%20PENDING%20--%3E%20EXPIRED%3A%20300s%20TTL%20expires%0A%20%20%20%20EXPIRED%20--%3E%20RELEASED%3A%20Rollback%20worker%20restores%20available%20stock%0A%20%20%20%20RELEASED%20--%3E%20%5B*%5D%3A%20Stock%20recycled%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h3 id="trace-implementation" tabindex="-1">Trace &amp; Implementation <a class="header-anchor" href="#trace-implementation" aria-label="Permalink to &quot;Trace &amp; Implementation&quot;">​</a></h3><ul><li><strong>Source Files</strong>: <code>backend/src/stock/reservation.py:122-180</code>, <code>backend/src/flow/checkout.py:84-110</code></li><li><strong>Key Functions</strong>: <code>release_reservation()</code>, <code>cleanup_expired_reservations()</code></li><li><strong>Data Touched</strong>: <code>reservations.status = &#39;EXPIRED&#39;</code>, <code>inventory.reserved -= qty</code>, <code>inventory.available += qty</code></li></ul><h3 id="say-it-out-loud" tabindex="-1">Say It Out Loud <a class="header-anchor" href="#say-it-out-loud" aria-label="Permalink to &quot;Say It Out Loud&quot;">​</a></h3><blockquote><p>&quot;I implemented automated hold expiration and stock rollback to prevent inventory hoarding and abandoned cart lockups.</p><p>When a buyer reserves an item, we give them a 300-second window to complete checkout. If the buyer closes their browser or their credit card fails, we cannot leave those items locked forever.</p><p>Our checkout service checks the reservation expiration timestamp against the clock before processing payment. If the lease has expired, the checkout request is rejected.</p><p>Concurrently, our background reconciliation worker scans for pending reservations where <code>expires_at &lt; now</code>. It atomically transitions the reservation status to <code>EXPIRED</code> and issues an update to decrement <code>reserved</code> stock and increment <code>available</code> stock by the exact reservation quantity.</p><p>This guarantees that abandoned inventory is automatically recycled back to the sale pool for other shoppers, maintaining 100% stock utilization.&quot;</p></blockquote>',4))])}const y=i(u,[["render",h]]);export{f as __pageData,y as default};
